.ng-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: Roboto, "Helvetica Neue", Arial, sans-serif;
  color: #222;
}
.ng-stage {
  position: absolute;
  left: 0;
  top: 0;
  transform-origin: 0 0;
}
.ng-stage > * { position: absolute; }

.ng-bg {
  left: 0;
  top: 0;
  width: 934px;
  height: 828px;
  pointer-events: none;
  user-select: none;
}

/* Státusz fejléc */
.ng-statusz {
  left: 0;
  top: 0;
  width: 585px;
  height: 88px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  font-size: 26px;
  font-weight: 700;
  color: #111;
}
.ng-st-led { width: 46px; height: 46px; }

.ng-logo {
  left: 146px;
  top: 138px;
  width: 300px;
  height: auto;
  pointer-events: none;
  user-select: none;
}

/* Reaktorok */
.ng-reaktor {
  top: 299px;
  width: 82px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}
.ng-reaktor-u { top: 278px; }
.ng-r-nev { font-size: 12.5px; font-weight: 700; line-height: 16px; color: #1c2333; }
.ng-r-al  { font-size: 9.5px;  font-weight: 700; line-height: 12px; color: #1c2333; }
.ng-r-ertek {
  margin-top: 25px;
  font-size: 15.5px;
  font-weight: 700;
  line-height: 24px;
  color: #111;
  white-space: nowrap;
}
.ng-r-led { margin-top: 17px; width: 40px; height: 40px; }

/* LED */
.ng-led {
  box-sizing: border-box;
  flex: none;
  border-radius: 50%;
  border: 3px solid #fff;
  background: #bdbdbd;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, .12), 0 2px 6px rgba(0, 0, 0, .22);
}
.ng-led.ok    { background: #2ecc71; }
.ng-led.rossz { background: #e74c3c; }
.ng-led.figy  { background: #f1c40f; }

/* Kártyák */
.ng-card {
  box-sizing: border-box;
  background: linear-gradient(135deg, rgba(255, 255, 255, .94) 0%, rgba(214, 236, 203, .9) 100%);
  border: 1px solid #b9dca6;
  border-radius: 22px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, .10);
}
.ng-cim {
  text-align: center;
  font-size: 18px;
  font-weight: 700;
  color: #222;
}

.ng-atfolyas { left: 939px; top: 12px; width: 299px; height: 264px; padding: 22px 22px 0; }
.ng-atfolyas .ng-cim { margin-bottom: 12px; }
.ng-p-sor {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 26.5px;
}
.ng-p-sor span { font-size: 14px; color: #444; }
.ng-p-sor b { font-size: 21px; font-weight: 700; color: #333; }
.ng-kis-led { width: 20px; height: 20px; border-width: 2px; }

.ng-ido     { left: 588px; top: 352px; width: 349px; height: 135px; padding-top: 18px; }
.ng-szenzor { left: 588px; top: 490px; width: 349px; height: 129px; padding-top: 24px; }
.ng-ido .ng-3 { margin-top: 18px; }
.ng-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  text-align: center;
}
.ng-o { display: flex; flex-direction: column; align-items: center; }
.ng-o-cim  { font-size: 14px; color: #444; line-height: 18px; }
.ng-o b    { font-size: 26px; font-weight: 700; color: #333; line-height: 40px; }
.ng-o-egys { font-size: 13px; color: #444; line-height: 18px; min-height: 18px; }
.ng-o .ng-led { width: 38px; height: 38px; margin-top: 10px; }

/* Átfolyás beállítása gomb (admin) */
.ng-sp-gomb {
  left: 686px;
  top: 24px;
  width: 227px;
  height: 79px;
  border: none;
  border-radius: 18px;
  background: linear-gradient(135deg, #a8d98a 0%, #6fb24f 100%);
  box-shadow: 0 4px 10px rgba(0, 0, 0, .18);
  color: #111;
  font-size: 19px;
  font-weight: 700;
  cursor: pointer;
}
.ng-sp-gomb:hover { filter: brightness(1.07); }

/* Dialógus */
.ng-hatter {
  position: absolute;
  inset: 0;
  z-index: 20;
  background: rgba(0, 0, 0, .35);
  display: flex;
  align-items: center;
  justify-content: center;
}
.ng-dialog {
  width: 340px;
  max-width: 92%;
  max-height: 94%;
  overflow: auto;
  box-sizing: border-box;
  padding: 18px 22px 16px;
  border-radius: 22px;
  background: linear-gradient(135deg, #ffffff 0%, #e4f2dc 100%);
  border: 1px solid #b9dca6;
  box-shadow: 0 12px 30px rgba(0, 0, 0, .25);
}
.ng-d-cim { margin-bottom: 10px; }
.ng-d-sor {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 9px 0;
  font-size: 14px;
  color: #333;
}
.ng-d-in { display: flex; align-items: center; gap: 6px; }
.ng-d-in input {
  width: 90px;
  height: 32px;
  box-sizing: border-box;
  border: 1px solid #cfe3c4;
  border-radius: 16px;
  padding: 0 12px;
  font-size: 14px;
  text-align: right;
  background: #fff;
  outline: none;
}
.ng-d-in input:focus { border-color: #7dbb5c; }
.ng-d-in input.ng-hiba { border-color: #e74c3c; }
.ng-d-in i { font-style: normal; font-size: 12px; color: #555; width: 46px; }
.ng-d-gombok { display: flex; justify-content: flex-end; gap: 10px; margin-top: 16px; }
.ng-g2 {
  height: 36px;
  padding: 0 20px;
  border: none;
  border-radius: 18px;
  background: linear-gradient(135deg, #a8d98a 0%, #6fb24f 100%);
  color: #111;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
}
.ng-g2.ng-masod { background: #eef6ea; color: #4d8a32; }
.ng-g2:disabled { opacity: .6; cursor: default; }

