// =====================================================================
//  NGN GÉP NÉZET widget
//  Widget típus: Legfrissebb értékek (Latest values), 1 datasource:
//  az adott gépnézet state aliasa (pl. "Gép #1")
// =====================================================================

// ------------------------- BEÁLLÍTÁSOK -------------------------------
const MOD = 'ugyfel';   // 'admin'  = pontos értékek + "Átfolyás beállítása" gomb
                       // 'ugyfel' = jó/rossz LED-ek

const KEPEK = {        // Képtár → kép → nyilvános (public) link
  gep:  '/api/images/public/cpfwkApOhjvYuKTGXWfNQfAsX9HTY92s',   // gép háttér (934×828)
  logo: '/api/images/public/t0cXxeb4jQpp3rTy6mGfHhxq6aB7t3Hs'    // NGN logó
};

const HATAR = {        // [alsó, felső] – ezen kívül piros a LED
  t:   [120, 500],     // hőmérséklet NYERS értéke (kijelzés: érték / 10)
  f:   [40, 47],       // átfolyás
  ai1: [5.5, 7.5],     // EC
  ai2: [1.5, 5],       // PH
  tds: [100, 200]      // TDS
};

const SP_SCOPE = 'SHARED_SCOPE';   // sp1…sp7 ide mentődik
// ---------------------------------------------------------------------

const SW = 1250, SH = 828;                       // a jelenet mérete
const RX = [48, 130, 211, 292, 373, 453, 534];   // reaktorok közepe a képen
const ADM = MOD === 'admin';

let root = null, stage = null, E = {};

self.onInit = function () {
  const c = self.ctx.$container[0];
  c.innerHTML = '';
  root = el('div', 'ng-root');
  c.appendChild(root);
  stage = el('div', 'ng-stage');
  stage.style.width = SW + 'px';
  stage.style.height = SH + 'px';
  stage.innerHTML = sablon();
  root.appendChild(stage);

  E = {};
  stage.querySelectorAll('[data-id]').forEach(function (n) { E[n.getAttribute('data-id')] = n; });
  if (E['sp-gomb']) E['sp-gomb'].addEventListener('click', dialogNyit);

  self.onResize();
  self.onDataUpdated();
};

self.onResize = function () {
  if (!stage) return;
  const W = self.ctx.width, H = self.ctx.height;
  if (!W || !H) return;
  const s = Math.min(W / SW, H / SH);
  const x = (W - SW * s) / 2, y = (H - SH * s) / 2;
  stage.style.transform = 'translate(' + x + 'px,' + y + 'px) scale(' + s + ')';
};

self.onDataUpdated = function () {
  if (!stage) return;

  // Státusz
  const aktiv = ertek('active');
  const online = aktiv === null ? true : igaz(aktiv);
  let cls, txt;
  if (!online)               { cls = 'rossz'; txt = 'Offline'; }
  else if (igaz(ertek('wrn'))) { cls = 'figy';  txt = 'Hiba'; }
  else if (igaz(ertek('run'))) { cls = 'ok';    txt = 'Működés'; }
  else                       { cls = 'rossz'; txt = 'Leállítva'; }
  led(E['st-led'], cls);
  E['st-txt'].textContent = txt;

  for (let i = 1; i <= 7; i++) {
    // Hőmérséklet
    const t = num(ertek('t' + i));
    if (ADM) E['t' + i].textContent = t === null ? '–' : (t / 10).toFixed(1) + ' °C';
    else led(E['t' + i], jo(t, HATAR.t));

    // Átfolyás
    const f = num(ertek('f' + i));
    if (ADM) E['f' + i].textContent = f === null ? '–' : f.toFixed(1) + ' ml/min';
    else led(E['f' + i], jo(f, HATAR.f));
  }

  // EC / PH / TDS
  const ec = num(ertek('ai1')), ph = num(ertek('ai2')), tds = num(ertek('tds'));
  if (ADM) {
    E['ai1'].textContent = ec === null ? '–' : ec.toFixed(1);
    E['ai2'].textContent = ph === null ? '–' : ph.toFixed(1);
    E['tds'].textContent = tds === null ? '–' : tds.toFixed(0);
  } else {
    led(E['ai1'], jo(ec, HATAR.ai1));
    led(E['ai2'], jo(ph, HATAR.ai2));
    led(E['tds'], jo(tds, HATAR.tds));
  }

  // Működési idő
  ['run_d', 'run_h', 'run_m'].forEach(function (k) {
    const v = num(ertek(k));
    E[k].textContent = v === null ? '–' : Math.floor(v);
  });
};

self.onDestroy = function () { root = null; stage = null; };

self.typeParameters = function () {
  return { maxDatasources: 1, maxDataKeys: -1, dataKeysOptional: false };
};

// ----------------------------- felépítés -----------------------------

function sablon() {
  let h = '';
  h += '<img class="ng-bg" src="' + KEPEK.gep + '" draggable="false">';
  h += '<div class="ng-statusz"><div class="ng-led ng-st-led" data-id="st-led"></div>' +
       '<span data-id="st-txt">–</span></div>';
  h += '<img class="ng-logo" src="' + KEPEK.logo + '" draggable="false">';

  for (let i = 1; i <= 7; i++) {
    h += '<div class="ng-reaktor' + (ADM ? '' : ' ng-reaktor-u') + '" style="left:' + (RX[i - 1] - 41) + 'px">' +
         '<div class="ng-r-nev">Reaktor #' + i + '</div><div class="ng-r-al">hőmérséklet</div>' +
         (ADM ? '<div class="ng-r-ertek" data-id="t' + i + '">–</div>'
              : '<div class="ng-led ng-r-led" data-id="t' + i + '"></div>') +
         '</div>';
  }

  if (ADM) h += '<button class="ng-sp-gomb" data-id="sp-gomb">Átfolyás beállítása</button>';

  h += '<div class="ng-card ng-atfolyas"><div class="ng-cim">Átfolyás</div>';
  for (let i = 1; i <= 7; i++) {
    h += '<div class="ng-p-sor"><span>Pumpa #' + i + '</span>' +
         (ADM ? '<b data-id="f' + i + '">–</b>' : '<div class="ng-led ng-kis-led" data-id="f' + i + '"></div>') +
         '</div>';
  }
  h += '</div>';

  h += '<div class="ng-card ng-ido"><div class="ng-cim">Működési idő</div><div class="ng-3">' +
       oszlop('Nap', '<b data-id="run_d">–</b>', null) +
       oszlop('Óra', '<b data-id="run_h">–</b>', null) +
       oszlop('Perc', '<b data-id="run_m">–</b>', null) +
       '</div></div>';

  h += '<div class="ng-card ng-szenzor"><div class="ng-3">' +
       szenzor('EC', 'ai1', 'µS/cm') + szenzor('PH', 'ai2', '') + szenzor('TDS', 'tds', 'ppm') +
       '</div></div>';
  return h;
}

function oszlop(cim, tartalom, egyseg) {
  return '<div class="ng-o"><span class="ng-o-cim">' + cim + '</span>' + tartalom +
         (egyseg === null ? '' : '<span class="ng-o-egys">' + egyseg + '</span>') + '</div>';
}

function szenzor(cim, kulcs, egyseg) {
  return ADM ? oszlop(cim, '<b data-id="' + kulcs + '">–</b>', egyseg)
             : oszlop(cim, '<div class="ng-led" data-id="' + kulcs + '"></div>', null);
}

// ------------------------ Átfolyás beállítása ------------------------

function dialogNyit() {
  const ds = (self.ctx.datasources || [])[0];
  if (!ds || !ds.entityId) { toast('Nincs gép hozzárendelve', true); return; }

  const hatter = el('div', 'ng-hatter');
  let h = '<div class="ng-dialog"><div class="ng-cim ng-d-cim">Átfolyás beállítása</div>';
  for (let i = 1; i <= 7; i++) {
    const v = num(ertek('sp' + i));
    h += '<label class="ng-d-sor"><span>Pumpa #' + i + '</span><span class="ng-d-in">' +
         '<input type="text" inputmode="decimal" data-sp="' + i + '" value="' + (v === null ? '' : v) + '">' +
         '<i>ml/perc</i></span></label>';
  }
  h += '<div class="ng-d-gombok"><button class="ng-g2 ng-masod" data-a="megse">Mégse</button>' +
       '<button class="ng-g2" data-a="ment">Mentés</button></div></div>';
  hatter.innerHTML = h;
  root.appendChild(hatter);

  const bezar = function () { hatter.remove(); };
  hatter.addEventListener('click', function (e) { if (e.target === hatter) bezar(); });
  hatter.querySelector('[data-a=megse]').addEventListener('click', bezar);
  hatter.querySelector('[data-a=ment]').addEventListener('click', function () {
    const gomb = this, attrs = [];
    let hibas = false;
    hatter.querySelectorAll('input[data-sp]').forEach(function (inp) {
      const s = inp.value.trim().replace(',', '.');
      if (s === '') return;
      const v = parseFloat(s);
      if (isNaN(v) || v < 0) { inp.classList.add('ng-hiba'); hibas = true; return; }
      inp.classList.remove('ng-hiba');
      attrs.push({ key: 'sp' + inp.getAttribute('data-sp'), value: v });
    });
    if (hibas || !attrs.length) return;
    gomb.disabled = true;
    self.ctx.attributeService.saveEntityAttributes(
      { entityType: ds.entityType, id: ds.entityId }, SP_SCOPE, attrs
    ).subscribe(
      function () { bezar(); toast('Átfolyás beállítva'); },
      function () { gomb.disabled = false; toast('A mentés nem sikerült', true); }
    );
  });
}

// ----------------------------- segédek -------------------------------

function ertek(kulcs) {
  const d = (self.ctx.data || []).find(function (e) { return e.dataKey && e.dataKey.name === kulcs; });
  if (!d || !d.data || !d.data.length) return null;
  return d.data[d.data.length - 1][1];
}

function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(v);
  return isNaN(n) ? null : n;
}

function igaz(v) { return v === true || v === 'true' || Number(v) === 1; }

function jo(v, hatar) {
  if (v === null) return null;
  return (v >= hatar[0] && v <= hatar[1]) ? 'ok' : 'rossz';
}

function led(n, cls) {
  if (!n) return;
  n.classList.remove('ok', 'rossz', 'figy');
  if (cls) n.classList.add(cls);
}

function toast(msg, hiba) {
  try { hiba ? self.ctx.showErrorToast(msg) : self.ctx.showSuccessToast(msg); }
  catch (e) { console.log(msg); }
}

function el(tag, cls) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  return e;
}

